}

/* Colour key, below the grid. It's lifted out of the flow into the card's own
   bottom padding, so it claims no row of its own and only its ink fades —
   revealing it never resizes the card or shifts anything below it. Invisible
   until the pointer is over the grid: a glanceable reference, not permanent
   chrome. Revealing on :hover of the legend too keeps it up while you read it. */
/* Grid and key side by side. The grid is the flexible one, so opening the key
   takes its width from the grid rather than widening the card; `min-width: 0`
   lets it actually shrink instead of holding its content's intrinsic width. */
.board-main { display: flex; align-items: stretch; gap: 0; }
.board-main > .cal-wrap { flex: 1 1 auto; min-width: 0; }

/* Closed, the key is `hidden` — display:none, so it occupies nothing at all and
   the grid has the full width back. Open, it's a fixed-width column: the marks
   are short labels and a column that flexed with them would jitter as the grid
   resized. */
.cal-legend {
  flex: 0 0 168px;
  margin-left: 16px; padding-left: 16px;
  border-left: 1px solid var(--line);
}
.cal-legend[hidden] { display: none; }
/* Stacked rather than the wrapping row it was under the grid — one mark per
   line reads as a key to scan down. */
.cal-legend .legend { flex-direction: column; gap: 9px; flex-wrap: nowrap; }

/* The header toggle, sitting next to Clear and matching its shape. Its `is-on`
   state is the panel's only other affordance, so it has to read as pressed. */
.board-legend-btn {
  flex: 0 0 auto; font: inherit; font-size: 0.78rem; font-weight: 600;
  color: var(--muted); background: #fff;
  border: 1px solid var(--line); border-radius: 999px;
  padding: 5px 13px; cursor: pointer;
}
.board-legend-btn:hover { color: var(--ink); border-color: #c9cedb; }
.board-legend-btn:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
.board-legend-btn.is-on {
  color: var(--violet); border-color: var(--violet);
  background: rgba(108, 76, 241, 0.07);
}
.board-legend-btn[hidden] { display: none; }

